ện</button></div><span class="auth-field__error" data-password-match></span></div></div><button class="auth-submit" type="submit" data-submit><span>Gửi hồ sơ xác minh</span><span>→</span></button></form><?php endif;?><p class="auth-switch">Đã có tài khoản? <a href="./login.php">Đăng nhập</a></p></div></section></main><script src="assets/js/auth.js" defer></script></body></html>
